from itertools import permutations

def find_all_interval_series(n):
    """Find an all-interval series of size n using backtracking."""
    def backtrack(perm, used_diffs, used_values):
        if len(perm) == n:
            return perm

        for val in range(n):
            if val not in used_values:
                if len(perm) == 0:
                    # First element, no diff constraint
                    perm.append(val)
                    used_values.add(val)
                    result = backtrack(perm, used_diffs, used_values)
                    if result:
                        return result
                    perm.pop()
                    used_values.remove(val)
                else:
                    diff = abs(val - perm[-1])
                    if diff not in used_diffs and 1 <= diff <= n-1:
                        perm.append(val)
                        used_diffs.add(diff)
                        used_values.add(val)
                        result = backtrack(perm, used_diffs, used_values)
                        if result:
                            return result
                        perm.pop()
                        used_diffs.remove(diff)
                        used_values.remove(val)
        return None

    return backtrack([], set(), set())

# Try to find for n=12
result = find_all_interval_series(12)
print(f"Result: {result}")
